{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_9c52aeaf480c149fff171467", "claim_ids": ["claim_6fe9164ac259327485f7632c", "claim_733d0e23849407f28f363e7c"], "query_ids": ["q_418"], "claims": [{"claim_id": "claim_6fe9164ac259327485f7632c", "quote": "| Permanent magnets | 25% | January 1, 2026 | 0% |", "url": "https://www.whitecase.com/insight-alert/united-states-finalizes-section-301-tariff-increases-imports-china", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Permanent magnets", "duty_rate": "25%", "effective_date": "January 1, 2026"}}, {"claim_id": "claim_733d0e23849407f28f363e7c", "quote": "Magnets (8505.11 / 8505.19) get a firm +25% on 1/1/2026", "url": "https://www.duramag.com/techtalk/magnet-news/understanding-the-2026-section-301-tariffs-on-permanent-magnets-what-the-market-needs-to-know", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}]}, {"pair_id": "conflict_eb93d2a9a597e41a4b946fdd", "claim_ids": ["claim_bedc47f823baab6c580b1029", "claim_bf51719aef2538109e6f8fdc"], "query_ids": ["q_418"], "claims": [{"claim_id": "claim_bedc47f823baab6c580b1029", "quote": "The January 2026 Section 301 increase was applied to 8505.11.00.", "url": "https://radialmagnet.com/magnet-tariffs-country-of-origin", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "8505.11.00", "effective_date": "January 2026"}}, {"claim_id": "claim_bf51719aef2538109e6f8fdc", "quote": "That ended on 1 January 2026, when a long-scheduled increase took effect adding 25% additional duty to permanent magnets of metal imported from China.", "url": "https://radialmagnet.com/magnet-tariffs-country-of-origin", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "effective_date": "1 January 2026"}}]}, {"pair_id": "conflict_6a5993dad4fe228e72e114e8", "claim_ids": ["claim_17fc36eff25ff2bebb434182", "claim_42ada07380f5378f4c512aee"], "query_ids": ["q_419"], "claims": [{"claim_id": "claim_17fc36eff25ff2bebb434182", "quote": "In 2012, Hitachi filed a complaint with the United States International Trade Commission (U.S. ITC) against 29 manufacturers and importers of sintered rare earth magnets and products containing sintered rare earth magnets.", "url": "https://www.federalregister.gov/documents/2023/02/14/2023-03078/publication-of-a-report-on-the-effect-of-imports-of-neodymium-iron-boron-ndfeb-permanent-magnets-on", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"company": "Hitachi", "legal_authority": "United States International Trade Commission (U.S. ITC)", "affected_product": "sintered rare earth magnets and products containing sintered rare earth magnets"}}, {"claim_id": "claim_42ada07380f5378f4c512aee", "quote": "China is the predominant source of imports to the United States, having increased its share of magnet imports to the United States in quantity from about 70 percent in 2016 to almost 85 percent in 2021 and in value from almost 60 percent in 2016 to about 75 percent in 2021.", "url": "https://www.federalregister.gov/documents/2023/02/14/2023-03078/publication-of-a-report-on-the-effect-of-imports-of-neodymium-iron-boron-ndfeb-permanent-magnets-on", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"exporting_country": "China", "duty_rate": "2.1 percent"}}]}, {"pair_id": "conflict_17a56a816dfe5af040bc84f8", "claim_ids": ["claim_177e6bb82870b68ef67a44e0", "claim_45bdafed8e0bb81dab9cb65b"], "query_ids": ["q_420"], "claims": [{"claim_id": "claim_177e6bb82870b68ef67a44e0", "quote": "China's suspension of enhanced graphite export controls to the United States until 27 November 2026 temporarily eases a key geopolitical bottleneck at the centre of the battery supply chain.", "url": "https://www.cruxinvestor.com/posts/chinas-temporary-easing-of-graphite-export-controls-the-shifting-global-supply-outlook-for-battery-materials", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "suspension of enhanced graphite export controls", "announcement_date": "9 November 2025", "effective_date": "27 November 2026"}}, {"claim_id": "claim_45bdafed8e0bb81dab9cb65b", "quote": "China has temporarily suspended enhanced graphite export controls to the United States until November 27, 2026, reducing immediate trade friction in the battery supply chain.", "url": "https://www.cruxinvestor.com/posts/chinas-temporary-easing-of-graphite-export-controls-the-shifting-global-supply-outlook-for-battery-materials", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "enhanced graphite export controls", "expiration_date": "November 27, 2026"}}]}, {"pair_id": "conflict_0ea4257f676e3ccfa959da22", "claim_ids": ["claim_d276325616ebb4e6092f0c4c", "claim_e993af0b5068d592ee6497e9"], "query_ids": ["q_420"], "claims": [{"claim_id": "claim_d276325616ebb4e6092f0c4c", "quote": "China's suspension of enhanced graphite export controls to the United States through November 2026 represents a tactical adjustment rather than a strategic shift in Beijing's approach to critical mineral trade.", "url": "https://www.cruxinvestor.com/posts/chinas-temporary-easing-of-graphite-export-controls-the-shifting-global-supply-outlook-for-battery-materials", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "enhanced graphite export controls", "expiration_date": "November 2026"}}, {"claim_id": "claim_e993af0b5068d592ee6497e9", "quote": "China's suspension of enhanced graphite export controls to the United States through November 2026 represents a tactical adjustment rather than a strategic shift in Beijing's approach to critical mineral trade.", "url": "https://www.cruxinvestor.com/posts/chinas-temporary-easing-of-graphite-export-controls-the-shifting-global-supply-outlook-for-battery-materials", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"expiration_date": "November 2026"}}]}, {"pair_id": "conflict_12bfd4bf651f56c8aca8ffed", "claim_ids": ["claim_26dd53d097011fcb280f1fac", "claim_319aff0be694ca369afb6676"], "query_ids": ["q_422"], "claims": [{"claim_id": "claim_26dd53d097011fcb280f1fac", "quote": "Indonesia’s decision did not have a direct or immediate impact on the production or importation of nickel in the United States.", "url": "https://www.nbr.org/publication/indonesias-nickel-export-ban-impacts-on-supply-chains-and-the-energy-transition", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_319aff0be694ca369afb6676", "quote": "the United States will maintain a 19% reciprocal tariff rate on imports from Indonesia", "url": "https://www.nusanickel.com/post/us-indonesia-trade-deal-finalized-what-it-signals-for-critical-minerals-and-nickel-flows", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "19%"}}]}, {"pair_id": "conflict_57d932ff8987d06cf9c1abf1", "claim_ids": ["claim_4ce7615d593580a12c74fb1a", "claim_77447a9143d3e1d3e1cef703"], "query_ids": ["q_423"], "claims": [{"claim_id": "claim_4ce7615d593580a12c74fb1a", "quote": "July 30, 2025: announcement of 50% tariff imposed on semi-finished copper products, effective August 1.", "url": "https://www.toprankedlegal.com/chile-and-tariffs-to-imports-into-the-u-s", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "July 30, 2025"}}, {"claim_id": "claim_77447a9143d3e1d3e1cef703", "quote": "On July 30, 2025, the United States imposed an additional 50% tariff on the value of the copper content of semi-finished or derived products with high copper content (e.g., tubes, wires, rods, sheets, electric cables, and copper-based accessories), effective from August 1, 2025.", "url": "https://www.toprankedlegal.com/chile-and-tariffs-to-imports-into-the-u-s", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "additional 50% tariff on the value of the copper content", "affected_product": "semi-finished or derived products with high copper content (e.g., tubes, wires, rods, sheets, electric cables, and copper-based accessories)", "effective_date": "August 1, 2025"}}]}, {"pair_id": "conflict_2ccd26ce38e2bb811771f0d7", "claim_ids": ["claim_1369d79355222d675627f8f7", "claim_987a765c7f92b49ab35e10f8"], "query_ids": ["q_423"], "claims": [{"claim_id": "claim_1369d79355222d675627f8f7", "quote": "There are products exempted from the application of this additional tariff, such as refined copper and wood, which continue to be exempt from tariffs on their import into the U.S., in accordance with the FTA.", "url": "https://www.toprankedlegal.com/chile-and-tariffs-to-imports-into-the-u-s", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {}}, {"claim_id": "claim_987a765c7f92b49ab35e10f8", "quote": "Exports from Chile to the U.S. will continue to be subject to the General Additional Tariff of 10%, which is applied over the 0% tariff established in the Free Trade Agreement (FTA) between both countries.", "url": "https://www.toprankedlegal.com/chile-and-tariffs-to-imports-into-the-u-s", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "10%"}}]}, {"pair_id": "conflict_d0bd82afa8f48c6a4b1dad3d", "claim_ids": ["claim_123286ded2dfbed976cbce55", "claim_65979a41e01b84c16185e67d"], "query_ids": ["q_424"], "claims": [{"claim_id": "claim_123286ded2dfbed976cbce55", "quote": "The US and Argentina have ratified the trade deal agreed in November which is set to eliminate tariffs on hundreds of products while expanding US beef access to the South American nation.", "url": "https://www.icis.com/explore/resources/news/2026/02/06/11178365/us-argentina-sign-trade-deal-focused-on-critical-minerals-beef-access", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "eliminate tariffs"}}, {"claim_id": "claim_65979a41e01b84c16185e67d", "quote": "Effective July 25, the policy maintains a 10% tariff baseline for Argentina while excluding strategic goods such as crude oil, beef, precious metals and aluminum.", "url": "https://www.agrolatam.com/usa/news/us-tariffs-argentina-exports-exempt-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "new tariff framework", "effective_date": "July 25"}}]}, {"pair_id": "conflict_6116b9dc0125aac247258be1", "claim_ids": ["claim_37de64a9070fd60fcde46387", "claim_65979a41e01b84c16185e67d"], "query_ids": ["q_424"], "claims": [{"claim_id": "claim_37de64a9070fd60fcde46387", "quote": "In exchange, the US will eliminate reciprocal tariffs imposed earlier this year on certain Argentine goods, particularly natural resources and pharmaceutical inputs.", "url": "https://www.icis.com/explore/resources/news/2026/02/06/11178365/us-argentina-sign-trade-deal-focused-on-critical-minerals-beef-access", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "eliminate reciprocal tariffs"}}, {"claim_id": "claim_65979a41e01b84c16185e67d", "quote": "Effective July 25, the policy maintains a 10% tariff baseline for Argentina while excluding strategic goods such as crude oil, beef, precious metals and aluminum.", "url": "https://www.agrolatam.com/usa/news/us-tariffs-argentina-exports-exempt-2026", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "new tariff framework", "effective_date": "July 25"}}]}]}

